/* wkaudio.c — implementation of wkaudio.h over the wit-bindgen C bindings.
 *
 * The bindings (gen/wkaudio.h + gen/wkaudio.c + gen/wkaudio_component_type.o)
 * are regenerated by each consumer's build.sh:
 *
 *     wit-bindgen c --world wkaudio ../audio-compat/wit --out-dir ../audio-compat/gen
 *
 * State is a single global context + pcm-queue: wk gives a node one audio
 * context, and the C apps this shim exists for (doomgeneric, ...) assume one
 * output stream. Both resources are intentionally never dropped — the host
 * tears the audio graph down when their handles drop, so they live in statics
 * for the guest's lifetime.
 */
#include "wkaudio.h"

#include <stddef.h>

#include "gen/wkaudio.h"

static struct {
    int open;
    uint32_t channels;
    wk_webaudio_audio_own_context_t ctx;
    wk_webaudio_audio_own_pcm_queue_t queue;
} G;

int wkaudio_open(float sample_rate, uint32_t channels)
{
    if (G.open)
        return -1;
    G.ctx = wk_webaudio_audio_constructor_context();
    G.queue = wk_webaudio_audio_method_context_create_pcm_queue(
        wk_webaudio_audio_borrow_context(G.ctx), sample_rate, channels);
    wk_webaudio_audio_method_pcm_queue_connect_destination(
        wk_webaudio_audio_borrow_pcm_queue(G.queue));
    G.channels = channels;
    G.open = 1;
    return 0;
}

double wkaudio_buffered(void)
{
    if (!G.open)
        return 0.0;
    return wk_webaudio_audio_method_pcm_queue_buffered(
        wk_webaudio_audio_borrow_pcm_queue(G.queue));
}

void wkaudio_write(const float *interleaved, uint32_t frames)
{
    if (!G.open || frames == 0)
        return;
    /* The import borrows the list, so the caller's buffer is passed straight
     * through without a copy (same as wkgfx_present's pixel list). */
    wkaudio_list_f32_t samples = {
        .ptr = (float *)interleaved,
        .len = (size_t)frames * G.channels,
    };
    wk_webaudio_audio_method_pcm_queue_write(
        wk_webaudio_audio_borrow_pcm_queue(G.queue), &samples);
}
